appearances.css:
:host{font-size:9px}
.app{display:flex;flex-wrap:wrap;gap:4px;align-items:flex-start;padding:6px;border-radius:0}
.app>*{flex:1 1 100%;min-width:0}
.row{display:flex;flex-wrap:wrap;gap:3px 4px;align-items:flex-end;margin:0}
.app>.row:nth-child(1){order:0;border:1px solid var(--line);border-radius:3px;padding:3px 4px 4px}
.app>.row:nth-child(1) .control{flex:1 1 50px;min-width:0;padding:0;border:0;gap:1px}
.app>.row:nth-child(1) .control:nth-child(1){flex:2.2 1 90px}
.app>.row:nth-child(1) .control:nth-child(2){flex:2 1 90px}
.control span{font-size:7.5px;line-height:1.1;letter-spacing:-.02em}
select,button{font-size:9px;padding:3px 2px;border-radius:3px}
select{appearance:none;-webkit-appearance:none;text-overflow:ellipsis}
.app>.row:nth-child(2){flex:1 1 170px;gap:3px 4px;align-items:center;order:6;border:1px solid var(--line);border-radius:3px;padding:3px 4px}
.app>.row:nth-child(2) button{flex:1 1 auto;padding:3px 4px}
.sec[data-lane=filter]{order:1}.sec[data-lane=amp]{order:2}.sec[data-lane=source]{order:3}.sec[data-lane=master]{order:4}.sec[data-lane=motion]{order:5}.sec[data-lane=routes]{order:7}
.app>canvas{order:8}.app>p{order:9}
.sec{flex:1 1 auto;border:1px solid var(--line);border-radius:3px;padding:3px 4px 4px;margin:0}
.sec h3{margin:0 0 2px;font-size:8px;letter-spacing:.14em;text-transform:uppercase;font-weight:600}
.sec .grid{display:flex;flex-wrap:wrap;gap:3px 0}
.control:has(.kn){display:grid;grid-template-columns:100%;justify-items:center;align-content:start;gap:0;padding:0;border:0;flex:0 0 52px}
.control:has(.kn) span{order:3;text-align:center;max-width:100%}
.control:has(.kn) output{order:2;font-size:8px;line-height:1.2;text-align:center}
.control:has(.kn) .kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.control .kn svg{width:100%;height:100%}
.app>.row:nth-child(2) .control:has(.kn){flex:0 0 52px}
.sec[data-lane=routes]{display:grid;grid-template-columns:1fr 1fr;gap:3px 8px;flex:1 1 100%}
.sec[data-lane=routes] h3{grid-column:1/-1}
.sec[data-lane=routes] .row{flex-wrap:nowrap;align-items:flex-end;gap:3px}
.sec[data-lane=routes] .row>span{font-size:9px;padding-bottom:6px}
.sec[data-lane=routes] .control{flex:1 1 0;min-width:0;padding:0;border:0;gap:1px}
.sec[data-lane=routes] .control:has(.kn){flex:0 0 52px}
canvas{height:34px}
p{margin:0;font-size:8px;line-height:1.2}
